// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und werden
// in der Data Table pw_config gepflegt (n8n-Oberfläche, "Data Tables").
// HIER stehen nur die FACHLICHEN Einstellungen dieses Workflows: Fristen,
// Tag-Namen, Feldnamen.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};
// zeitraum_tage: Rückblick auf neu hinzugekommene Dokumente.
// altlast_tage:  Inbox-Dokumente älter als X Tage gelten als Altlast.
const zeitraum_tage = 7;
const altlast_tage = 14;

const datum_neu = new Date(Date.now() - zeitraum_tage * 86400000).toISOString().slice(0, 10);
const datum_altlast = new Date(Date.now() - altlast_tage * 86400000).toISOString().slice(0, 10);

return [{
  json: {
    // ── aus der Data Table pw_config ──
    paperless_url:             pw('paperless_url'),
    paperless_url_oeffentlich: pw('paperless_url_oeffentlich'),
    empfaenger_email:          pw('mail_betrieb'),
    absender:                  pw('mail_absender'),

    // ── fachlich, hier zu pflegen ──
    ki_zusammenfassung: true,
    max_ki_docs: 20,
    mistral_model: 'mistral-small-latest',
    zeitraum_tage,
    altlast_tage,
    datum_neu,
    datum_altlast
  }
}];

// KI-Anfrage für die Einzeiler vorbereiten (ein einziger Mistral-Aufruf
// für alle neuen Dokumente, gedeckelt auf max_ki_docs).
const cfg = $('Konfiguration').first().json;
const neue = $('Neue Dokumente laden').first().json.results || [];
const kandidaten = neue.slice(0, cfg.max_ki_docs);
const ki_aktiv = !!cfg.ki_zusammenfassung && kandidaten.length > 0;

let mistralBody = null;
if (ki_aktiv) {
  const docList = kandidaten.map(d => ({
    id: d.id,
    titel: d.title || '(kein Titel)',
    auszug: String(d.content || '').replace(/\s+/g, ' ').slice(0, 400),
  }));

  const SYSTEM_PROMPT = `Du bekommst eine Liste von Dokumenten aus einem Paperless-Dokumentenmanagementsystem (je Titel und Textauszug). Fasse JEDES Dokument in genau einem kurzen deutschen Satz zusammen (max. 15 Wörter): Wer schreibt, worum geht es, ggf. Betrag oder Frist.

Regeln:
- Keine Floskeln, keine Wiederholung des Titels, keine Vermutungen über Inhalte außerhalb des Auszugs
- Antworte ausschließlich mit gültigem JSON in genau diesem Format:
{"zusammenfassungen": {"<dokument-id>": "<ein Satz>", ...}}`;

  mistralBody = {
    model: cfg.mistral_model,
    response_format: { type: 'json_object' },
    temperature: 0.2,
    max_tokens: 1500,
    messages: [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: JSON.stringify(docList) },
    ],
  };
}

return [{ json: { ki_aktiv, mistralBody } }];

// Digest-Mail aufbauen. Läuft in beiden Zweigen (mit/ohne KI);
// die KI-Sätze werden fail-soft geholt: klappt das Parsen nicht,
// kommt der Digest ohne Zusammenfassungen.
const cfg = $('Konfiguration').first().json;
const neue = $('Neue Dokumente laden').first().json.results || [];
const inbox = $('Inbox-Altlasten laden').first().json.results || [];
const ohneKorr = $('Ohne Korrespondent laden').first().json.results || [];

let sums = {};
try {
  const raw = $('Mistral zusammenfassen').first().json?.choices?.[0]?.message?.content;
  if (typeof raw === 'string' && raw.trim()) {
    const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    const parsed = JSON.parse(cleaned);
    if (parsed && typeof parsed.zusammenfassungen === 'object') sums = parsed.zusammenfassungen;
  }
} catch (e) { sums = {}; }

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = (iso) => iso ? new Date(iso).toLocaleDateString('de-DE') : '-';
const link = (d) => '<a href="' + cfg.paperless_url_oeffentlich + '/documents/' + d.id + '/detail" style="color:#1a73e8;">' + esc(d.title || '(kein Titel)') + '</a>';

// Abschnitt 1: neue Dokumente.
let neuHtml;
if (neue.length) {
  const rows = neue.map(d => '<tr>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;">' + link(d) + '</td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;white-space:nowrap;">' + fmt(d.added) + '</td>'
    + '<td style="padding:6px 12px;border:1px solid #ddd;font-size:13px;color:#555;">' + esc(sums[String(d.id)] ?? sums[d.id] ?? '') + '</td>'
    + '</tr>').join('\n');
  neuHtml = '<table cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px;width:100%;margin:8px 0 20px 0;">'
    + '<thead><tr style="background:#2c3e50;color:#fff;">'
    + '<th style="padding:8px 12px;text-align:left;">Dokument</th>'
    + '<th style="padding:8px 12px;text-align:left;">Hinzugef\u00fcgt</th>'
    + '<th style="padding:8px 12px;text-align:left;">Zusammenfassung</th>'
    + '</tr></thead><tbody>' + rows + '</tbody></table>';
} else {
  neuHtml = '<p style="color:#555;">Keine neuen Dokumente in den letzten ' + cfg.zeitraum_tage + ' Tagen.</p>';
}

// Abschnitte 2 + 3: Altlasten (jeweils auf 15 Zeilen gekürzt).
const altListe = (docs) => {
  if (!docs.length) return '<p style="color:#27ae60;">Nichts offen \u2713</p>';
  const items = docs.slice(0, 15).map(d => '<li>' + link(d) + ' <span style="color:#888;font-size:12px;">(seit ' + fmt(d.added) + ')</span></li>').join('');
  const mehr = docs.length > 15 ? '<p style="font-size:12px;color:#888;">\u2026 und ' + (docs.length - 15) + ' weitere.</p>' : '';
  return '<ul style="margin:8px 0;">' + items + '</ul>' + mehr;
};

const today = new Date().toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin' });
const html = '<div style="font-family:Arial,sans-serif;max-width:750px;">'
  + '<h2 style="color:#2c3e50;border-bottom:2px solid #2c3e50;padding-bottom:8px;">Paperless Wochen-Digest</h2>'
  + '<h3 style="color:#2c3e50;">\ud83d\udce5 Neu in den letzten ' + cfg.zeitraum_tage + ' Tagen (' + neue.length + ')</h3>'
  + neuHtml
  + '<h3 style="color:#2c3e50;">\ud83d\udcca Inbox-Altlasten \u2014 unbearbeitet seit \u00fcber ' + cfg.altlast_tage + ' Tagen (' + inbox.length + ')</h3>'
  + altListe(inbox)
  + '<h3 style="color:#2c3e50;">\u2753 Ohne Korrespondent \u2014 \u00e4lter als ' + cfg.altlast_tage + ' Tage (' + ohneKorr.length + ')</h3>'
  + altListe(ohneKorr)
  + '<p><a href=' + cfg.paperless_url_oeffentlich + ' style="background:#2c3e50;color:#fff;padding:8px 16px;text-decoration:none;border-radius:4px;display:inline-block;">&#8594; Paperless-NGX \u00f6ffnen</a></p>'
  + '<p style="color:#95a5a6;font-size:12px;margin-top:32px;border-top:1px solid #eee;padding-top:12px;">Automatisch generiert am ' + today + ' \u00b7 <a href="https://github.com/paper-werk">Paper-Werk</a></p>'
  + '</div>';

return [{ json: {
  html,
  toEmail: cfg.empfaenger_email,
  fromEmail: cfg.absender,
  subject: 'Paperless Wochen-Digest: ' + neue.length + ' neu, ' + (inbox.length + ohneKorr.length) + ' offen'
} }];
